-- Stacked Cozy Fires: one fire per hearth instead of two to five on the same point.
-- 2026_11_18_926_world_everlake_stacked_cozy_fires.sql: written by hand, the row list made by a script.
--
-- Reported in game: the campfire at Hillsbrad Foothills 33.0 34.6 looked doubled. The fork's baseline (and the Forever
-- TDB it comes from) spawns 2 to 5 Cozy Fire objects (all display 199) within 3 yards of each other at 87 places,
-- mostly house fireplaces in the Eastern Kingdoms and Theramore, many with their own Campfire trap (2061) on the same
-- point: 247 fires and 193 traps.
--
-- Each place's fires were split into levels by height (1 yard apart or more) and the surfaces under each level read
-- from Everlake's maps and vmaps (tools/height.py --floors of wow-forever-tracker, client 70790's files). 105 levels
-- stand on a floor (a house model, or terrain within 1 yard): each keeps its lowest guid fire and that fire's trap.
-- One level has no floor: the upper pair at Hillsbrad (-337, 9, z 60.5) floats 4.4 yards over terrain where no house
-- model stands, and is removed whole; the lower level there keeps 30018228 and its trap 30018285.
-- Deleted: 142 fires and their 115 traps (257 rows). No other world table names these guids, and no later custom or
-- world-data file touches them.
-- A row is deleted only while it is still as the baseline has it (guid, entry, map and position). Running it again
-- changes nothing. Not checked in game.
-- Never edit this file once it is deployed: a later fix is a new file.

DROP TEMPORARY TABLE IF EXISTS `everlake_stacked_fires`;
CREATE TEMPORARY TABLE `everlake_stacked_fires` (
  `guid` bigint unsigned NOT NULL,
  `id` int unsigned NOT NULL,
  `map` smallint unsigned NOT NULL,
  `x` float NOT NULL,
  `y` float NOT NULL,
  `z` float NOT NULL,
  PRIMARY KEY (`guid`)
);

-- guid, entry, map, x, y, z -- the place (the level's first fire) it stands at

DELETE g FROM `gameobject` g
  JOIN `everlake_stacked_fires` d ON d.`guid` = g.`guid` AND d.`id` = g.`id` AND d.`map` = g.`map`
   AND ABS(g.`position_x` - d.`x`) < 0.01 AND ABS(g.`position_y` - d.`y`) < 0.01 AND ABS(g.`position_z` - d.`z`) < 0.01;

DROP TEMPORARY TABLE `everlake_stacked_fires`;
